import "golang.org/x/sync/singleflight"

var requestGroup singleflight.Group

func GetUserProfile(userID string) (Profile, error) {
    // 1. Try Cache First
    if profile, found := cache.Get(userID); found {
        return profile, nil
    }

    // 2. Cache Miss -> Use Singleflight to deduplicate concurrent requests
    // If 1,000 requests for 'userID' hit this line simultaneously, 'FetchFromDB' 
    // is only executed ONCE. The other 999 requests block and wait for the result.
    result, err, _ := requestGroup.Do(userID, func() (interface{}, error) {

        // 3. Fetch from DB
        dbProfile, dbErr := fetchFromDB(userID)
        if dbErr != nil { return nil, dbErr }

        // 4. Populate Cache
        cache.Set(userID, dbProfile, 5 * time.Minute)
        return dbProfile, nil
    })

    if err != nil { return Profile{}, err }
    return result.(Profile), nil
}
